% 中文图42B：四泳道热图（AudioOnly、WaterOnly、NaiveAudioWater、LearnedAudioWater）

if ~exist('TransferLearning', 'class')
	matlab.project.loadProject(fullfile(fileparts(fileparts(mfilename('fullpath'))), 'Transferlearning.prj'));
end

DS = TransferLearning.AudioLightBaseline();
xsSec = seconds(TransferLearning.Xs);

baseMask = xsSec >= -3 & xsSec < 0;

[~,idx1s] = min(xsSec-1,[],ComparisonMethod='abs');

QueryTable=cell2table({ ...
	"AudioOnly"	"AudioOnly"		[]; ...
	"WaterOnly"	"WaterOnly"		[]; ...
	"Naive"		"AudioWater"	"Naive"; ...
	"Learned"	"AudioWater"	"Learned"},VariableNames=["GroupName","Stimulus","Phase"]);
%%
X = UniExp.NtatsCellStrip(DS.QueryNTATS(QueryTable,UniExp.Flags.ZScore, 1:24, UniExp.Flags.Median));
cellMouse = iGetCellMouse(DS, X.CellUID);
activeMask = any(X.NTATS{:,idx1s,:}> mean(X.NTATS{:, baseMask, :}, 2) + 3 * std(X.NTATS{:, baseMask, :}, [], 2), 3);

X = UniExp.HeatmapSort(X(activeMask, :),@(T)T(:,idx1s,:),["Naive","Learned"]).NTATS;
%%

X = X(:, xsSec >= -2 & xsSec <= 2, :);
%%
f = figure(Name='中文图42B 四泳道热图',Units='centimeters'); %[output:7cbf4fac]
f.Position(3:4) = [12, 8]; %[output:7cbf4fac]

Layout = tiledlayout(f, 1, 4, TileSpacing='tight',Padding='tight'); %[output:7cbf4fac]

[~, Axes] = UniExp.LanearHeatmap( ... %[output:7cbf4fac]
	X.Data, ... %[output:7cbf4fac]
	SubTitles=["", "", "Naive", "Learned"], ... %[output:7cbf4fac]
	Flags=[UniExp.Flags.HideYAxis, UniExp.Flags.SymmetricColormap], ... %[output:7cbf4fac]
	CLim=[-sqrt(-min(X.Data, [], 'all')), sqrt(max(X.Data, [], 'all'))], ... %[output:7cbf4fac]
	Layout=Layout, ... %[output:7cbf4fac]
	ImagescStyle={'XData', [-2,2]}, ... %[output:7cbf4fac]
	LMHColor=[TransferLearning.HeatmapNegative; 1,1,1; TransferLearning.HeatmapPositive]); %[output:7cbf4fac]

xlabel(Layout, 'Time'); %[output:7cbf4fac]
ylabel(Layout, sprintf('%u cells', height(X))); %[output:7cbf4fac]

CB = colorbar; %[output:7cbf4fac]
CB.Layout.Tile = 'east'; %[output:7cbf4fac]
CB.Label.String = 'z-score'; %[output:7cbf4fac]
CB.Box = 'off'; %[output:7cbf4fac]

for iA = 1:numel(Axes)
	A = Axes(iA);
	A.FontName = 'Segoe UI Emoji'; %[output:7cbf4fac]
	A.TickDir="in";
	xline(A, 0, '--', 'LineWidth', 2);
	xlim(A, [-1 2]);
end
Axes(1).XTickLabel(Axes(1).XTick==0) = {"🔊"}; %[output:7cbf4fac]
Axes(2).XTickLabel(Axes(2).XTick==0) = {"💧"}; %[output:7cbf4fac]
xlim(Axes(2), [-2 1]); %[output:7cbf4fac]
for iA=3:4
	A = Axes(iA);
	A.XTickLabel(ismember(A.XTick,[0,1])) = {"🔊", "💧"}; %[output:7cbf4fac]
	xline(A, 1, '--', 'LineWidth', 2);
end

outDirUNC = fullfile('\\Data-Server-2\个人数据\张天夫', char(datetime('now', 'Format', 'yyyyMM')));
if ~isfolder(outDirUNC)
	mkdir(outDirUNC);
end

svgPath = TransferLearning.ExportStandardFigure(f, 2, '中文图Fig42B_FourLaneHeatmap_AudioWater.svg'); %[output:7cbf4fac]
fprintf('Fig42B mice plotted after active-cell filter: %u\n', numel(unique(cellMouse(activeMask)))); %[output:6453c0a3]

function cellMouse = iGetCellMouse(DS, cellUID)
cellMeta = DS.Cells(:, ["CellUID", "Mouse"]);
[~, loc] = ismember(cellUID, cellMeta.CellUID);
cellMouse = cellMeta.Mouse(loc);
end

